+// API keys and roles. Keys live in the data as `apiKeys` (docs/DATA.md).
+// A role includes everything the roles before it may do.
+import { createHash, timingSafeEqual } from "node:crypto";
+import { AppError } from "../errors.js";
+
+/** Roles, least to most powerful. */
+export const ROLES = ["viewer", "cook", "manager"];
+
+const digest = (text) => createHash("sha256").update(String(text)).digest();
+
+/** The API key record for `key`; throws `unauthorized` when missing or unknown. */
+export function authenticate(store, key) {
+  if (typeof key !== "string" || key === "") throw new AppError("unauthorized");
+  const wanted = digest(key);
+  let found = null;
+  for (const k of store.data.apiKeys ?? []) {
+    if (typeof k.key === "string" && k.key !== "" && timingSafeEqual(digest(k.key), wanted)) found ??= k;
+  }
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless `role` may call a `method` route; `needs` is the route's own minimum role. */
+export function authorize(role, method, needs = null) {
+  const required = needs ?? (method === "GET" ? "viewer" : "manager");
+  const have = ROLES.indexOf(role);
+  if (have === -1 || have < ROLES.indexOf(required)) throw new AppError("forbidden");
+}
